extension=r"""
/* GroupBlock v1: additive visibility, stable IDs, complete variant export. */
let gbEditorGroupId='',gbOverride=null,gbExportBusy=false;
function gbKey(name){return String(name||'').trim().toLocaleLowerCase();}
function gbAllBlocks(model=M){const byId=new Map();Object.entries(model.rigsByDir||{}).filter(([d])=>d!==model.dir).forEach(([,r])=>(r.blocks||[]).forEach(b=>byId.set(String(b.id),b)));(model.blocks||[]).forEach(b=>byId.set(String(b.id),b));return byId;}
function normalizeBlockGroups(model){
 const valid=gbAllBlocks(model),owned=new Set(),gids=new Set(),gnames=new Set();
 const unique=(value,used,fallback)=>{let name=String(value||fallback).trim()||fallback,base=name,n=2;while(used.has(gbKey(name)))name=base+' '+n++;used.add(gbKey(name));return name;};
 model.blockGroups=(Array.isArray(model.blockGroups)?model.blockGroups:[]).map((raw,i)=>{const g=raw&&typeof raw==='object'?raw:{},id=unique(g.id,gids,'group_'+(i+1)),name=unique(g.name,gnames,'Group '+(i+1)),vids=new Set(),vnames=new Set();const variants=(Array.isArray(g.variants)?g.variants:[]).map((raw,j)=>{const v=raw&&typeof raw==='object'?raw:{},blockIds=[];for(const n of Array.isArray(v.blockIds)?v.blockIds:[]){const key=String(n);if(valid.has(key)&&!owned.has(key)){owned.add(key);blockIds.push(+key);}}return{id:unique(v.id,vids,id+'_variant_'+(j+1)),name:unique(v.name,vnames,'Bộ '+(j+1)),blockIds};});const selected=typeof g.selectedVariantId==='string'?g.selectedVariantId:variants[0]?.id||'';return{id,name,selectedVariantId:variants.some(v=>v.id===selected)?selected:'',variants};});return model.blockGroups;
}
function gbGroups(){return M.blockGroups||(M.blockGroups=[]);}
function groupBlockVisible(blockId){for(const g of gbGroups())for(const v of g.variants)if(v.blockIds.some(id=>String(id)===String(blockId)))return(gbOverride?gbOverride[g.id]:g.selectedVariantId)===v.id;return true;}
function withGroupBlockPlan(plan,callback){const old=gbOverride;gbOverride=plan.selections;try{return callback();}finally{gbOverride=old;}}
function gbStatus(text){$('gbStatus').textContent=text;}
function showRightTab(tab){const on=tab==='groupblock';$('propertiesPane').hidden=on;$('groupBlockPane').hidden=!on;for(const[id,active]of[['tabProperties',!on],['tabGroupBlock',on]]){$(id).classList.toggle('active',active);$(id).setAttribute('aria-selected',String(active));}if(on)renderGroupBlocks();}
function gbNextId(prefix,ids){let n=1;while(ids.has(prefix+n))n++;return prefix+n;}
function gbSelect(gid,vid){const g=gbGroups().find(g=>g.id===gid);if(!g||(vid&&!g.variants.some(v=>v.id===vid)))return false;checkpointUndo();g.selectedVariantId=vid;renderAll();draw();return true;}
// Named API for preview/testing; the matching Unity API is the next stage.
function setGroupVariant(groupName,variantName){const g=gbGroups().find(g=>gbKey(g.name)===gbKey(groupName));if(!g){gbStatus('Không có group: '+groupName);return false;}const name=String(variantName??'').trim(),v=g.variants.find(v=>gbKey(v.name)===gbKey(name));if(name&&!v){gbStatus('Không có bộ '+name+' trong '+g.name);return false;}return gbSelect(g.id,v?.id||'');}
function gbCreateGroup(){const input=$('gbNewGroupName'),name=input.value.trim();if(!name)return gbStatus('Nhập tên group trước.');if(gbGroups().some(g=>gbKey(g.name)===gbKey(name)))return gbStatus('Tên group đã tồn tại.');checkpointUndo();const g={id:gbNextId('group_',new Set(gbGroups().map(g=>g.id))),name,selectedVariantId:'',variants:[]};gbGroups().push(g);gbEditorGroupId=g.id;input.value='';renderAll();gbStatus('Đã tạo '+name+'. Thêm bộ rồi kéo block từ Skeleton vào.');}
function gbRemoveGroup(gid){const i=gbGroups().findIndex(g=>g.id===gid);if(i<0)return;checkpointUndo();gbGroups().splice(i,1);renderAll();draw();gbStatus('Đã bỏ group; các block gốc vẫn ở Skeleton. Có thể Undo.');}
function gbCreateVariant(gid){const g=gbGroups().find(g=>g.id===gid),name=$('gbNewVariantName').value.trim();if(!g)return;if(!name||g.variants.some(v=>gbKey(v.name)===gbKey(name)))return gbStatus('Tên bộ phải khác rỗng và không trùng trong group.');checkpointUndo();const v={id:gbNextId(g.id+'_variant_',new Set(g.variants.map(v=>v.id))),name,blockIds:[]};g.variants.push(v);g.selectedVariantId=v.id;renderAll();draw();gbStatus('Kéo block từ Skeleton vào '+name+' hoặc thêm block đang chọn.');}
function gbRemoveVariant(gid,vid){const g=gbGroups().find(g=>g.id===gid);if(!g)return;checkpointUndo();g.variants=g.variants.filter(v=>v.id!==vid);if(g.selectedVariantId===vid)g.selectedVariantId='';renderAll();draw();gbStatus('Đã bỏ bộ, không xóa block gốc. Có thể Undo.');}
function gbAssignBlock(gid,vid,id){const g=gbGroups().find(g=>g.id===gid),v=g?.variants.find(v=>v.id===vid),b=gbAllBlocks().get(String(id));if(!v||!b)return gbStatus('Chỉ nhận Block từ Skeleton.');checkpointUndo();for(const gr of gbGroups())for(const vr of gr.variants)vr.blockIds=vr.blockIds.filter(n=>String(n)!==String(id));v.blockIds.push(+id);renderAll();draw();gbStatus('Đã gán '+b.name+' vào '+g.name+' / '+v.name+'.');}
function gbRemoveMember(gid,vid,id){const v=gbGroups().find(g=>g.id===gid)?.variants.find(v=>v.id===vid);if(!v)return;checkpointUndo();v.blockIds=v.blockIds.filter(n=>String(n)!==String(id));renderAll();draw();}
function gbCurrentSelections(){return Object.fromEntries(gbGroups().map(g=>[g.id,g.selectedVariantId]));}
function gbSelectionFields(selections,kind){return gbGroups().map(g=>`<div class="row"><label title="${esc(g.name)}">${esc(g.name)}</label><select aria-label="${esc(g.name)}" data-gb-select="${kind}" data-group="${esc(g.id)}"><option value="">Không chọn / tay không</option>${g.variants.map(v=>`<option value="${esc(v.id)}" ${selections[g.id]===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div>`).join('')||'<p class="gb-note">Chưa có group; xuất ảnh như bản gốc.</p>';}
function renderGroupBlocks(){
 if(!$('gbEditor'))return;const groups=gbGroups();$('gbPreviewSelections').innerHTML=gbSelectionFields(gbCurrentSelections(),'preview');const g=groups.find(g=>g.id===gbEditorGroupId)||groups[0];gbEditorGroupId=g?.id||'';
 if(!g){$('gbEditor').innerHTML='<p class="gb-note">Tạo group (Weapon), thêm bộ (Kiếm, Rìu), rồi kéo block vào bộ. Mỗi block chỉ thuộc một bộ duy nhất trên toàn model.</p>';return;}const blocks=gbAllBlocks();
 $('gbEditor').innerHTML=`<h4>Chỉnh group</h4><div class="row"><select id="gbEditGroupSelect" aria-label="Group cần chỉnh">${groups.map(x=>`<option value="${esc(x.id)}" ${x.id===g.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>
 <div class="gb-heading"><input aria-label="Đổi tên group" data-gb-name="group" data-group="${esc(g.id)}" value="${esc(g.name)}"><button data-gb-action="remove-group" data-group="${esc(g.id)}">Bỏ group</button></div>
 <div class="row"><input id="gbNewVariantName" placeholder="Tên bộ, ví dụ Kiếm" aria-label="Tên bộ mới"><button data-gb-action="add-variant" data-group="${esc(g.id)}">＋ Bộ</button></div><p class="gb-note">Kéo block sẽ chuyển liên kết cũ sang bộ mới. Danh sách dùng ID block giữa các hướng; không ghi đè keyframe.</p>
 ${g.variants.map(v=>`<div class="gb-card ${g.selectedVariantId===v.id?'selected':''}"><div class="gb-heading"><input aria-label="Đổi tên bộ" data-gb-name="variant" data-group="${esc(g.id)}" data-variant="${esc(v.id)}" value="${esc(v.name)}"><button data-gb-action="remove-variant" data-group="${esc(g.id)}" data-variant="${esc(v.id)}">Bỏ bộ</button></div><div class="gb-drop" data-group="${esc(g.id)}" data-variant="${esc(v.id)}">${v.blockIds.map(id=>`<div class="gb-member"><span>▣ ${esc(blocks.get(String(id))?.name||'Block không còn tồn tại')} (#${id})</span><button data-gb-action="remove-member" data-group="${esc(g.id)}" data-variant="${esc(v.id)}" data-block="${id}" aria-label="Bỏ liên kết block">×</button></div>`).join('')||'Thả block từ Skeleton vào đây'}</div><button style="width:100%" data-gb-action="add-selection" data-group="${esc(g.id)}" data-variant="${esc(v.id)}">＋ Thêm block đang chọn</button></div>`).join('')}`;
}
$('groupBlockPane').addEventListener('click',e=>{const b=e.target.closest('[data-gb-action]');if(!b)return;const{gbAction:a,group:g,variant:v,block:id}=b.dataset;if(a==='remove-group')gbRemoveGroup(g);else if(a==='add-variant')gbCreateVariant(g);else if(a==='remove-variant')gbRemoveVariant(g,v);else if(a==='remove-member')gbRemoveMember(g,v,id);else if(a==='add-selection'){if(sel?.t!=='k')gbStatus('Chọn một Block ở Skeleton trước.');else gbAssignBlock(g,v,sel.id);}});
$('groupBlockPane').addEventListener('change',e=>{const el=e.target;if(el.dataset.gbSelect==='preview')return gbSelect(el.dataset.group,el.value);if(el.id==='gbEditGroupSelect'){gbEditorGroupId=el.value;renderGroupBlocks();return;}if(!el.dataset.gbName)return;const g=gbGroups().find(g=>g.id===el.dataset.group);if(!g)return;const item=el.dataset.gbName==='group'?g:g.variants.find(v=>v.id===el.dataset.variant),siblings=el.dataset.gbName==='group'?gbGroups():g.variants,name=el.value.trim();if(!item)return;if(!name||siblings.some(x=>x!==item&&gbKey(x.name)===gbKey(name))){el.value=item.name;return gbStatus('Tên phải khác rỗng và không trùng.');}checkpointUndo();item.name=name;renderGroupBlocks();gbStatus('Đã đổi tên; ID và liên kết giữ nguyên.');});
$('groupBlockPane').addEventListener('dragover',e=>{const z=e.target.closest('.gb-drop');if(!z)return;e.preventDefault();z.classList.add('drag-target');if(e.dataTransfer)e.dataTransfer.dropEffect='move';});
$('groupBlockPane').addEventListener('dragleave',e=>{const z=e.target.closest('.gb-drop');if(z&&!z.contains(e.relatedTarget))z.classList.remove('drag-target');});
$('groupBlockPane').addEventListener('drop',e=>{const z=e.target.closest('.gb-drop');if(!z)return;e.preventDefault();e.stopPropagation();const match=/^k:(\d+)$/.exec(e.dataTransfer?.getData('text/plain')||''),p=treeDragPayload;treeDragPayload=null;z.classList.remove('drag-target');if(p?.type==='k')gbAssignBlock(z.dataset.group,z.dataset.variant,p.id);else if(match)gbAssignBlock(z.dataset.group,z.dataset.variant,+match[1]);else gbStatus('Chỉ kéo Block từ Skeleton, không phải Bone/ảnh.');});
function gbUnityGroups(){return gbGroups().map(g=>({id:g.id,name:g.name,selectedVariantId:g.selectedVariantId,selectedVariantName:g.variants.find(v=>v.id===g.selectedVariantId)?.name||'',variants:g.variants.map(v=>({id:v.id,name:v.name,blockIds:[...v.blockIds]}))}));}
function gbValidateGroups(){const errors=[],blocks=gbAllBlocks(),owned=new Set(),names=new Set();for(const g of gbGroups()){if(!g.name.trim()||names.has(gbKey(g.name)))errors.push('Tên group rỗng/trùng: '+g.name);names.add(gbKey(g.name));const vn=new Set();for(const v of g.variants){if(!v.name.trim()||vn.has(gbKey(v.name)))errors.push('Tên bộ rỗng/trùng trong '+g.name);vn.add(gbKey(v.name));for(const id of v.blockIds){const k=String(id);if(!blocks.has(k))errors.push('Group '+g.name+' trỏ block đã xóa #'+id+'; bỏ liên kết trước khi xuất.');if(owned.has(k))errors.push('Block #'+id+' thuộc nhiều bộ.');owned.add(k);}}}return errors;}
function gbReadSelections(id){return Object.fromEntries([...$(id).querySelectorAll('select[data-group]')].map(el=>[el.dataset.group,el.value]));}
function gbPlan(selections,i){return{id:'set_'+i,selections:{...selections},labels:gbGroups().map(g=>({groupId:g.id,groupName:g.name,variantId:selections[g.id]||'',variantName:g.variants.find(v=>v.id===selections[g.id])?.name||''}))};}
function gbSpritePlans(){if($('gbSpriteMode').value!=='all')return[gbPlan(gbReadSelections('gbSpriteSelections'),1)];let count=1;const choices=gbGroups().map(g=>{const opts=g.variants.map(v=>v.id);if($('gbIncludeNone').checked||!opts.length)opts.unshift('');count*=opts.length;return{g,opts};});if(count>64)throw new Error(count+' tổ hợp vượt giới hạn 64; chọn bộ cụ thể hoặc giảm số bộ.');let rows=[{}];for(const{g,opts}of choices)rows=rows.flatMap(p=>opts.map(id=>({...p,[g.id]:id})));return rows.map((p,i)=>gbPlan(p,i+1));}
function gbSpriteEntries(sets,dirs,plans){const entries=plans.flatMap(plan=>dirs.flatMap(dir=>sets.map(set=>({set,dir,plan,bounds:withGroupBlockPlan(plan,()=>calculateSpriteBoundsForSets([set],dir)),count:spriteFrameCount(set,dir),startRow:0,rows:0}))));for(const set of sets)for(const dir of dirs){const same=entries.filter(e=>e.set===set&&e.dir===dir),minX=Math.min(...same.map(e=>e.bounds.minX)),minY=Math.min(...same.map(e=>e.bounds.minY)),maxX=Math.max(...same.map(e=>e.bounds.maxX)),maxY=Math.max(...same.map(e=>e.bounds.maxY));for(const e of same)e.bounds={minX,minY,maxX,maxY,width:maxX-minX,height:maxY-minY};}return entries;}
function gbInitSpriteExport(){$('gbSpriteMode').value='selected';$('gbIncludeNone').checked=false;$('gbSpriteSelections').innerHTML=gbSelectionFields(gbCurrentSelections(),'export');gbSyncSpriteExport();}
function gbSyncSpriteExport(){const all=$('gbSpriteMode').value==='all';$('gbSpriteSelections').querySelectorAll('select').forEach(el=>el.disabled=all);$('gbIncludeNone').disabled=!all;try{$('gbExportInfo').textContent=gbSpritePlans().length+' bộ sẽ xuất. Không đổi lựa chọn mặc định của model.';}catch(error){$('gbExportInfo').textContent=error.message;}}
function gbInitAssetExport(){$('gbAssetScope').value='image';$('gbAssetSelections').innerHTML=gbSelectionFields(gbCurrentSelections(),'assets');gbSyncAssetExport();}
function gbSyncAssetExport(){const scope=$('gbAssetScope').value;$('gbAssetSelections').hidden=scope!=='selected';$('downloadAssetBtn').textContent=scope==='image'?'⬇ Tải PNG':'⬇ Tải ZIP';}
async function gbEnsureImages(){await Promise.all(LIB.filter(n=>imageData[n]).map(async name=>{const im=imageCache[name]||(imageCache[name]=new Image());if(!im.src)im.src=imageData[name];if(!(im.complete&&im.naturalWidth))await im.decode();}));}
function gbSafeFile(text){return String(text).normalize('NFC').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').replace(/[. ]+$/,'')||'unnamed';}
function gbAssetJobs(scope,selections){const jobs=[],rigs={...M.rigsByDir,[M.dir]:{blocks:M.blocks}};let index=0;for(const g of gbGroups())for(const v of g.variants){if(scope!=='all'&&selections[g.id]!==v.id)continue;const names=new Set();for(const rig of Object.values(rigs))for(const b of rig.blocks||[])if(v.blockIds.some(id=>String(id)===String(b.id)))for(const key of ['img','imgUp','imgLeft','imgRight'])if(b[key])names.add(b[key]);for(const set of M.animationSets)for(const anim of Object.values(set.dirs))for(const states of Object.values(anim.blockKeys||{}))for(const st of states)if(st.image&&v.blockIds.some(id=>String(id)===String(st.blockId)))names.add(st.image);for(const name of names){if(!imageData[name])throw new Error('Thiếu ảnh '+name);jobs.push({name,path:`${++index}_${gbSafeFile(g.name)}/${gbSafeFile(v.name)}/${gbSafeFile(name).replace(/\.[^.]+$/,'')}.png`});}}return jobs;}
// Store-only UTF-8 ZIP, no external package/CDN required.
function gbZip(files){const enc=new TextEncoder(),local=[],central=[];let offset=0;function crc32(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;}for(const file of files){const name=enc.encode(file.path),data=file.bytes,crc=crc32(data),h=new Uint8Array(30+name.length),d=new DataView(h.buffer);d.setUint32(0,0x04034b50,true);d.setUint16(4,20,true);d.setUint16(6,0x800,true);d.setUint32(14,crc,true);d.setUint32(18,data.length,true);d.setUint32(22,data.length,true);d.setUint16(26,name.length,true);h.set(name,30);local.push(h,data);const c=new Uint8Array(46+name.length),v=new DataView(c.buffer);v.setUint32(0,0x02014b50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint16(8,0x800,true);v.setUint32(16,crc,true);v.setUint32(20,data.length,true);v.setUint32(24,data.length,true);v.setUint16(28,name.length,true);v.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=h.length+data.length;}const size=central.reduce((n,b)=>n+b.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,size,true);e.setUint32(16,offset,true);return new Blob([...local,...central,end],{type:'application/zip'});}
async function downloadSelectedAsset(){const scope=$('gbAssetScope').value;if(scope==='image')return downloadSelectedAssetOriginal();const button=$('downloadAssetBtn'),status=$('imageActionStatus');button.disabled=true;try{const jobs=gbAssetJobs(scope,gbReadSelections('gbAssetSelections'));if(!jobs.length)throw new Error('Bộ đã chọn chưa có ảnh; thêm block vào group hoặc chọn bộ khác.');const size=+$('assetDownloadSize').value,files=[];status.textContent='Đang đóng gói '+jobs.length+' ảnh…';for(const job of jobs){const im=new Image();im.src=imageData[job.name];await im.decode();const c=document.createElement('canvas');c.width=size||im.naturalWidth;c.height=size||im.naturalHeight;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(im,0,0,c.width,c.height);const png=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!png)throw new Error('Không tạo được PNG '+job.name);files.push({path:job.path,bytes:new Uint8Array(await png.arrayBuffer())});}files.push({path:'groupblock-manifest.json',bytes:new TextEncoder().encode(JSON.stringify({scope,blockGroups:gbUnityGroups(),selections:gbReadSelections('gbAssetSelections'),files:jobs},null,2))});await downloadBlob(gbZip(files),gbSafeFile($('mn').value||'Character')+'_groupblocks_'+scope+'.zip');status.textContent='Đã tải ZIP gồm '+jobs.length+' PNG và manifest. Không đổi ảnh gốc/model.';}catch(error){status.textContent='Lỗi: '+error.message;}finally{button.disabled=false;}}
"""
